(function () {
    function applyHeroCTA() {
      if (typeof ABTest === 'undefined') return;
      var btn = document.getElementById('hero-cta-btn');
      if (!btn) return;
      var variant = ABTest.assign('hero-cta-copy', ['A', 'B']);
      if (variant === 'B') btn.textContent = '名前を診断してみる';
      btn.dataset.abVariant = variant;
      if (typeof Analytics !== 'undefined') {
        btn.addEventListener('click', function () {
          Analytics.ctaClicked('hero-cta-' + variant, 'home-hero');
        }, { once: true });
      }
    }
    if (document.readyState !== 'loading') applyHeroCTA();
    else document.addEventListener('DOMContentLoaded', applyHeroCTA);
  })();
